<!-- generated by studio，请勿手工修改。 -->
<template>
  <ContentWrap>
    <el-form ref="queryFormRef" :inline="true" :model="queryParams" class="-mb-15px">
        <el-form-item label="材料名称" prop="materialName">
          <el-input v-model="queryParams.materialName" clearable placeholder="请输入材料名称" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="规范编码" prop="normativeEncoding">
          <el-input v-model="queryParams.normativeEncoding" clearable placeholder="请输入规范编码" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="备注1" prop="note1">
          <el-input v-model="queryParams.note1" clearable placeholder="请输入备注1" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="备注2" prop="note2">
          <el-input v-model="queryParams.note2" clearable placeholder="请输入备注2" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="备注3" prop="note3">
          <el-input v-model="queryParams.note3" clearable placeholder="请输入备注3" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="备注4" prop="note4">
          <el-input v-model="queryParams.note4" clearable placeholder="请输入备注4" @keyup.enter="handleQuery" />
        </el-form-item>
      <el-form-item>
        <el-button @click="handleQuery"><Icon class="mr-5px" icon="ep:search" />查询</el-button>
        <el-button @click="resetQuery"><Icon class="mr-5px" icon="ep:refresh" />重置</el-button>
          <el-button type="primary" @click="openForm('create')">
            <Icon class="mr-5px" icon="ep:plus" />新增
          </el-button>
          <el-button :loading="exportLoading" type="success" @click="handleExport">
            <Icon class="mr-5px" icon="ep:download" />导出
          </el-button>
          <el-button :disabled="checkedIds.length === 0" type="danger" @click="handleDeleteBatch">
            <Icon class="mr-5px" icon="ep:delete" />批量删除
          </el-button>
      </el-form-item>
    </el-form>
  </ContentWrap>

  <ContentWrap>
    <el-table v-loading="loading" :data="rows" @selection-change="handleSelectionChange">
        <el-table-column align="center" type="selection" width="55" />
      <el-table-column align="center" label="行号" width="90">
        <template #default="scope">{{ (queryParams.pageNo - 1) * queryParams.pageSize + scope.$index + 1 }}</template>
      </el-table-column>
        <el-table-column label="上级id" prop="pid" min-width="120" show-overflow-tooltip />
        <el-table-column label="表头" prop="header" min-width="120" show-overflow-tooltip />
        <el-table-column label="材料名称" prop="materialName" min-width="120" show-overflow-tooltip />
        <el-table-column label="检验依据" prop="inspectionBasis" min-width="120" show-overflow-tooltip />
        <el-table-column label="规范编码" prop="normativeEncoding" min-width="120" show-overflow-tooltip />
        <el-table-column label="排序" prop="sortNo" min-width="120" show-overflow-tooltip />
        <el-table-column label="备注1" prop="note1" min-width="120" show-overflow-tooltip />
        <el-table-column label="备注2" prop="note2" min-width="120" show-overflow-tooltip />
        <el-table-column label="备注3" prop="note3" min-width="120" show-overflow-tooltip />
        <el-table-column label="备注4" prop="note4" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunDelegationOrderContextForm ref="formRef" @success="getList" />
  <BoxunDelegationOrderContextDetail ref="detailRef" />
</template>

<script setup lang="ts">
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunDelegationOrderContextApi from './BoxunDelegationOrderContextApi'
import BoxunDelegationOrderContextForm from './BoxunDelegationOrderContextForm.vue'
import BoxunDelegationOrderContextDetail from './BoxunDelegationOrderContextDetail.vue'

type BoxunDelegationOrderContextRow = Awaited<ReturnType<typeof BoxunDelegationOrderContextApi.getBoxunDelegationOrderContextPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunDelegationOrderContext' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunDelegationOrderContextRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  materialName: '',
  normativeEncoding: '',
  note1: '',
  note2: '',
  note3: '',
  note4: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunDelegationOrderContextApi.getBoxunDelegationOrderContextPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunDelegationOrderContextApi.deleteBoxunDelegationOrderContext(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunDelegationOrderContextRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunDelegationOrderContextApi.deleteBoxunDelegationOrderContextList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/delegation-order-context/export-excel', params: queryParams })
    download.excel(data, 'boxunDelegationOrderContext.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
